ST.xhtml:p:
R_Trigger1(CLK := bY3JogForwardEnable OR bY3JogBackwardEnable);
F_Trigger2(CLK := bY3JogForwardEnable OR bY3JogBackwardEnable);
R_Trigger3(CLK := bY2JogForwardEnable OR bY2JogBackwardEnable);
F_Trigger4(CLK := bY2JogForwardEnable OR bY2JogBackwardEnable);

IF R_Trigger1.Q THEN
  nY3State := 1;
END_IF;
IF F_Trigger2.Q THEN
  nY3State := 0;
END_IF;

IF bY3JogFast THEN
  g_Y3MoveJog.Mode := 1;
ELSE
  g_Y3MoveJog.Mode := 0;
END_IF;

CASE nY3State OF 
  0:
    g_Y3MoveJog.JogForward := FALSE;
    g_Y3MoveJog.JogBackwards := FALSE;
    nY3State := 0;
  1:
    g_bAvoidOpen := TRUE;
    nY3State := 10;
  10:
    IF g_bAvoidDone THEN
      nY3State := 20;
    END_IF;
  20:
    g_Y3MoveJog.JogForward := bY3JogForwardEnable;
    g_Y3MoveJog.JogBackwards := bY3JogBackwardEnable;
END_CASE;

IF R_Trigger3.Q THEN
  nY2State := 1;
END_IF;
IF F_Trigger4.Q THEN
  nY2State := 0;
END_IF;

IF bY2JogFast THEN
  g_Y2MoveJog.Mode := 1;
ELSE
  g_Y2MoveJog.Mode := 0;
END_IF;

CASE nY2State OF 
  0:
    g_Y2MoveJog.JogForward := FALSE;
    g_Y2MoveJog.JogBackwards := FALSE;
    nY2State := 0;
  1:
    g_bAvoidOpen := TRUE;
    nY2State := 10;
  10:
    IF g_bAvoidDone THEN
      nY2State := 20;
    END_IF;
  20:
    g_Y2MoveJog.JogForward := bY2JogForwardEnable;
    g_Y2MoveJog.JogBackwards := bY2JogBackwardEnable;
END_CASE;

IF g_bPlcResetBuffer THEN
  bY2JogForwardEnable := FALSE;
  bY2JogBackwardEnable := FALSE;
  bY3JogForwardEnable := FALSE;
  bY3JogBackwardEnable := FALSE;
END_IF;
